(* [comment removed for export] *)
Definition bincr_err_stmt (pc : Z) : Prop := forall (cur : Z) rax ra sp gp tp t0 t1 t2 a0x a1x a3x a4x a5x a6x a7x s7x s9x s10x s11x
    s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (A W lo : Z) (wbs : list byte) (fst La : Z) (j8 : list byte),
  bctor_ctx m m1 sp (tk_saved s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) A W lo wbs cur fst La j8 -> tokit_pure sp A W lo wbs fst La ->
  evt bsegs (tokit_post_c (TokItCells 0 0 La La La) (Some A) ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc A W lo wbs m)
    (MS (bincr_regs rax (Z_to_bv 64 (bv_unsigned sp + -112)) gp tp t0 t1 t2 a0x a1x (wz La) a3x a4x a5x a6x a7x s7x s9x s10x s11x t3 t4 t5 t6 A)
        F (Z_to_bv 64 pc) fc None m1 (seg_rom bsegs)).

Local Ltac bincr_err_tac :=
  unfold bincr_err_stmt;
  intros cur rax ra sp gp tp t0 t1 t2 a0x a1x a3x a4x a5x a6x a7x s7x s9x s10x s11x s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v t3 t4 t5 t6
    F fc m m1 A W lo wbs fst La j8 CTX PURE; pose proof PURE as PURE';
  destruct CTX as (FR & V & OBJ & WIN & ST & MU & WM & MI & SD);
  destruct PURE' as (HLA & LA64 & FST & SEPW & LO & CEIL & SEPA & SEPS & AL & WNZ);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof (aobj_pos _ _ _ (proj1 (proj2 SD))) as (A0 & _ & AHI);
  pose proof aceil_facts as (AF1 & _);
  hydeL SEPW; hydeL SEPA; hydeL SEPS; hydeL AL;
  unfold TokItCells, SZ_TOKIT, TOKIT_STACK, AINTRIN_STACK, AAPP_HI, BNOT_TAB_TCHAR, tk_saved in *; unfold wz in *;
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  unfold bincr_regs, wz; rewrite ASHADOW_BASE_val;
  (* [comment removed for export] *)
  tk_ochk SD MU WM CEIL A 16 AL ltac:(idtac; step);
  st1;
  tk_ochk SD MU WM CEIL A 24 AL ltac:(idtac; step);
  st1;
  eapply bincr_epi; [exact FR| | exact WIN| exact ST| exact MU| exact WM| exact MI| exact SD| exact PURE];
