(* [comment removed for export] *)
Local Ltac call_sows OBJ SD MU WM CEIL ST MI WIN SEPW SEPA SEPS AL WNZ A cur La W wbs lo sp :=
  let CELL := fresh "CELL" in let O3 := fresh "O3" in let SS := fresh "SS" in
  let ACc := fresh "ACc" in let AOc := fresh "AOc" in let AWc := fresh "AWc" in
  lazymatch type of OBJ with rw_cells _ _ _ [?c3; ?c4; ?c5] => split_frameA OBJ [c3] [c4; c5] CELL O3 end;
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) => destruct (tk_side_now _ mc _ _ _ _ _ SD MU WM CEIL) as (ACc & AOc & AWc) end;
  pose proof skip_ows_spec as SS; unfold skip_ows_stmt, skip_ows_post, P_B_SKIP_OWS, SKIP_OWS_STACK in SS; unfold wz in SS;
  callZc (SS (A + 16) cur La W wbs lo) (clear SS CELL ST);
  [ exact CELL | exact WIN | lia | lia | lia | clear - SEPW; unhideL; lia
  | rewrite ?unsigned_lit by lia; exact ST | rewrite ?unsigned_lit by lia; lia | exact CEIL
  | rewrite ?unsigned_lit by lia; clear - SEPA; unhideL; lia | rewrite ?unsigned_lit by lia; clear - SEPS; unhideL; lia
  | exact MI
  | clear - AL; unhideL; Z.div_mod_to_equations; lia
  | eapply aobj_sub_acc; [exact AOc| lia| lia| unfold SZ_TOKIT; lia]
  | eapply awin_sub; [exact (aobj_awin _ _ _ AOc)| lia| unfold SZ_TOKIT; lia]
  | intros _; exact AWc | exact ACc | exact WNZ | ];
  clear ACc AOc AWc;
  try match goal with H : bytes_at _ _ W _, H' : bytes_at _ _ W _ |- _ => clear H' end;
  lazymatch goal with H : bytes_at _ _ W _ |- _ => try rename H into WIN end;
  lazymatch goal with C' : rw_cells _ _ (A + 16) [C8 _] |- _ => join_frameA C' O3 (A + 16); rename C' into OBJ end.

