Lemma bincr_loop : forall (mu i : nat) (nc : bool) (fst : Z) rax ra sp gp tp t0 t1 t2 a1x a4x a5x a6x a7x s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (A W lo : Z) (wbs : list byte) (La : Z) (j8 : list byte),
  (length wbs - i < mu)%nat -> (i < length wbs)%nat ->
  (forall b, nth_error wbs i = Some b -> is_ws (zb b) = false) ->
  bctor_ctx m m1 sp (tk_saved s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) A W lo wbs (W + Z.of_nat i) fst La j8 -> tokit_pure sp A W lo wbs fst La ->
  evt bsegs (tokit_post_c (tokit_cells_gen (tok_next nc (skipn i (zbytes wbs))) (W + Z.of_nat i) fst La) (Some A)
               ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc A W lo wbs m)
    (MS (bincr_regs rax (Z_to_bv 64 (bv_unsigned sp + -112)) gp tp t0 t1 t2 (wz (W + Z.of_nat i)) a1x (wz La)
              (wz (if nc then 1 else 0)) a4x a5x a6x a7x (wz 167040) (wz 44) (wz BNOT_TAB_TCHAR) (wz 2) t3 t4 t5 t6 A)
        F (Z_to_bv 64 0xbfa4c) fc None m1 (seg_rom bsegs)).
